select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('template-code','کد قالب','text',true,10,'{}'),('template-title','عنوان قالب','text',true,20,'{}'),('template-key','کلید قالب','text',true,30,'{}'),('notification-type','نوع اعلان','select',true,40,'{"options":["اطلاع‌رسانی","موفقیت","هشدار","خطا","اقدام","سیستمی"]}'),('channel','کانال','select',true,50,'{"options":["داخل سامانه","مرکز اعلان","پیامک","ایمیل","اعلان مرورگر"]}'),('subject-reference','مرجع عنوان','text',false,60,'{}'),('body-reference','مرجع متن','text',true,70,'{}'),('variables-reference','مرجع متغیرها','text',false,80,'{}'),('locale','زبان','select',true,90,'{"options":["fa-IR","en-US","ar"]}'),('version','نسخه','number',true,100,'{}'),('status','وضعیت','select',true,110,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('published-at','زمان انتشار','text',false,120,'{}'),('owner','مالک','text',false,130,'{}'),('description','توضیحات','textarea',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='40-notification-templates' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
